# CUDA kernel source for basic matrix multiplication
cuda_source = """
#include <torch/extension.h>

__global__ void matmul_kernel(const float* x, const float* w, float* out, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; k++) {
            sum += x[row * N + k] * w[k * N + col];
        }
